// color palette

var colors   =  ["#ff0000","#feb30f","#0aa4f7","#000000","#ffffff"];

// set weights for each color 

// red, blue, and white dominates 

var weights  = [0,1,1,1,1];             

// scale of the vector field 
// smaller values => bigger structures  
// bigger values  ==> smaller structures 


// number of drawing agents 

var nAgents = 200;

let agent = [];

function setup() {
  createCanvas(800,800);
	//createCanvas(1280,720);
  colorMode(HSB, 360, 100, 100);
	rectMode(CENTER);
  strokeCap(SQUARE);

  background(0);


  for(let i=0;i < nAgents;i++)
  {
		agent.push(new Agent(randomGaussian()*200,0));
    agent.push(new Agent(width*0.5 + randomGaussian()*200,0));
		agent.push(new Agent(width*1.0 + randomGaussian()*200,0));
	}


}

function draw() {

  if (frameCount > 10000)
  {
    // noLoop() removed for animation
  }

  for(let i=0;i < agent.length;i++)
  {
    agent[i].update(0,0);
  }


	stroke(0,0,100);
	noFill();
	strokeWeight(20);


}


// paintining agent 

class Agent {
  constructor(x0,y0)
  {
      this.p     = createVector(x0,y0);
      this.direction = 1;
      this.color = generateColor(10);
			this.scale = 10;
			this.strokeWidth = 5;
		  this.step = 2;
      this.pOld  = createVector(this.p.x,this.p.y);
		  this.split = 4;
  }

  update(xx,yy) {

    this.p.x += this.direction*vector_field(this.p.x,this.p.y,this.scale).x*this.step + 1;
    this.p.y += this.direction*vector_field(this.p.x,this.p.y,this.scale).y*this.step;

		this.strokeWidth = map(this.p.y,0,height,5,1);

		if (this.p.y >= height)
		{
			this.p.y = 0;
			this.color = generateColor(10);
		  this.pOld.set(this.p);
			this.strokeWidth = 5;
		}

    strokeWeight(this.strokeWidth);
    stroke(this.color);
    line(this.pOld.x,this.pOld.y,this.p.x,this.p.y);

    this.pOld.set(this.p);

  }

}

// vector field function 
// the painting agents follow the flow defined 
// by this function 


function vector_field(x,y,myScale) {

  x = map(x,0,width,-myScale - 10,myScale + 10);
  y = map(y,0,height,-myScale - 10,myScale + 10);

  let k1 = 5;
  let k2 = 3;

	let u = sin(k1*y) + floor(cos(k2*y));
  let v = sin(k2*x) - cos(k1*x);

  // litle trick to move from left to right 

  if (v <= 0) 
  {
      v = -v*0.5;
   }  


  return createVector(u,v);
}

// select colors with some weights 

function generateColor(scale) {
	let temp = myRandom(colors, weights);

	myColor = color(hue(window.color(temp)) + randomGaussian() * scale,
		              saturation(window.color(temp)) + randomGaussian() * scale,
		              brightness(window.color(temp)) - scale, 
									random(10,100));

	return myColor;
}


// function to select 

function myRandom(colors,weights)
{ 
    let sum = 0;

    for(let i=0;i < colors.length; i++)
    {
      sum += weights[i];
    }

    let rr = random(0,sum);

    for(let j=0;j < weights.length;j++)
    {

      if (weights[j] >= rr)
      {
        return colors[j];
      }
        rr -= weights[j];
    }
 }
